"""UUID v7 identifiers generated by the application (ADR-0006).

UUID v7 embeds a millisecond timestamp in its most significant bits, so values are
time-ordered: index locality on insert and a stable sort key for cursor pagination. Python 3.12
has no :func:`uuid.uuid7`, so it is implemented here against RFC 9562 §5.7.

Within a single millisecond the 12-bit ``rand_a`` field is used as a counter (RFC 9562 §6.2
"replace leftmost random bits with increased clock precision"), which keeps ids monotonic per
process instead of randomly ordered inside the millisecond.
"""

from __future__ import annotations

import os
import threading
import time
from uuid import UUID

_VERSION = 7
_VARIANT = 0b10
_TIMESTAMP_BITS = 48
_COUNTER_BITS = 12
_COUNTER_MAX = (1 << _COUNTER_BITS) - 1
# Seed the per-millisecond counter low so a burst has room to increment before rolling over.
_COUNTER_SEED_MAX = 0xFF
_RAND_B_BITS = 62
_RAND_B_MASK = (1 << _RAND_B_BITS) - 1


class _Uuid7Generator:
    """Thread-safe UUID v7 source with a monotonic intra-millisecond counter."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._timestamp_ms = -1
        self._counter = 0

    def _next_timestamp_and_counter(self) -> tuple[int, int]:
        now_ms = time.time_ns() // 1_000_000
        with self._lock:
            if now_ms > self._timestamp_ms:
                self._timestamp_ms = now_ms
                self._counter = int.from_bytes(os.urandom(1), "big") & _COUNTER_SEED_MAX
            elif self._counter >= _COUNTER_MAX:
                # More than 3,840 ids in one millisecond: borrow from the next millisecond
                # rather than emitting a non-monotonic value.
                self._timestamp_ms += 1
                self._counter = int.from_bytes(os.urandom(1), "big") & _COUNTER_SEED_MAX
            else:
                self._counter += 1
            return self._timestamp_ms, self._counter

    def next(self) -> UUID:
        timestamp_ms, counter = self._next_timestamp_and_counter()
        value = (timestamp_ms & ((1 << _TIMESTAMP_BITS) - 1)) << 80
        value |= _VERSION << 76
        value |= counter << 64
        value |= _VARIANT << 62
        value |= int.from_bytes(os.urandom(8), "big") & _RAND_B_MASK
        return UUID(int=value)


_generator = _Uuid7Generator()


def uuid7() -> UUID:
    """Return a new time-ordered UUID v7."""
    return _generator.next()


def uuid7_timestamp_ms(value: UUID) -> int:
    """Extract the embedded millisecond timestamp from a UUID v7."""
    if value.version != _VERSION:
        msg = f"not a UUID v7: {value}"
        raise ValueError(msg)
    return value.int >> 80
